-- Fictional catalog orders with real ownership claims; transaction rolls back.
begin;
create temporary table th_sample_results(stage text,result text) on commit drop;
create function pg_temp.th_sample_claim(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.th_sample_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'SAMPLE ASSERT FAILED: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('96000000-7a21-4000-8000-000000000001','sample-buyer@example.invalid',now(),'{}'),('96000000-7a21-4000-8000-000000000002','sample-other@example.invalid',now(),'{}');
do $$declare buyer uuid:='96000000-7a21-4000-8000-000000000001';other_user uuid:='96000000-7a21-4000-8000-000000000002';reply jsonb;state jsonb;oid uuid;cancel_oid uuid;expired_oid uuid;receipt text;begin
 perform pg_temp.th_sample_claim(other_user);perform public.th_api('snapshot');perform pg_temp.th_sample_claim(buyer);perform public.th_api('snapshot');
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');
 perform pg_temp.th_sample_assert(state->'sampleCommerce'='true'::jsonb,'sample capability');
 select v into reply from jsonb_array_elements(state->'products')x(v) where v->>'id'='p15';perform pg_temp.th_sample_assert(reply->'purchasableDemo'='true'::jsonb and reply->'isDemo'='true'::jsonb,'fixed samples purchasable with honest demo badge');
 select v into reply from jsonb_array_elements(state->'products')x(v) where v->>'id'='p14';perform pg_temp.th_sample_assert(not(reply?'purchasableDemo'),'sample auctions remain display only');
 begin perform public.th_api('cart_add','{"productId":"p15"}');raise exception 'Anonymous sample cart accepted';exception when sqlstate 'PT401' then null;end;
 perform pg_temp.th_sample_claim(buyer);
 update auth.users set email_confirmed_at=null where id=buyer;
 begin perform public.th_api('cart_add','{"productId":"p15"}');raise exception 'Unconfirmed sample cart accepted';exception when sqlstate 'PT403' then null;end;
 update auth.users set email_confirmed_at=now() where id=buyer;
 perform public.th_api('cart_add','{"productId":"p15"}');reply:=public.th_api('cart_add','{"productId":"p15"}');
 perform pg_temp.th_sample_assert(reply->'cart' @> '["p15"]'::jsonb and (select count(*)=1 from public.th_sample_cart where user_id=buyer),'sample cart persisted and repeated add deduplicated');
 begin perform public.th_api('cart_add','{"productId":"p14"}');raise exception 'Sample auction cart accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.th_api('reserve','{"productIds":["p15","96000000-7a21-4000-8000-000000000099"],"delivery":"pickup","requestKey":"sample-mixed-order-01"}');raise exception 'Mixed sample and real accepted';exception when sqlstate 'PT400' then null;end;
 begin perform public.th_api('reserve','{"productIds":["p15","p15"],"delivery":"pickup","requestKey":"sample-duplicate-order-01"}');raise exception 'Duplicate sample accepted';exception when sqlstate 'PT400' then null;end;
 reply:=public.th_api('reserve','{"productIds":["p15","p13"],"delivery":"pickup","requestKey":"sample-main-order-01","total":1}');oid:=(reply->>'orderId')::uuid;
 state:=public.th_api('snapshot');select v into reply from jsonb_array_elements(state->'orders')x(v) where v->>'id'=oid::text;
 perform pg_temp.th_sample_assert(reply->>'source'='sample' and reply->'paymentRequired'='true'::jsonb and (reply->>'total')::int=1640 and not(state->'cart' @> '["p15"]'::jsonb),'sample orders merged and server priced, cart cleared');
 reply:=public.th_api('reserve','{"productIds":["p13","p15"],"delivery":"pickup","requestKey":"sample-main-order-01"}');perform pg_temp.th_sample_assert(reply->>'orderId'=oid::text,'reordered sample retry same order');
 begin perform public.th_api('reserve','{"productIds":["p15"],"delivery":"pickup","requestKey":"sample-main-order-01"}');raise exception 'Sample reserve key mismatch accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.th_api('sample_complete',jsonb_build_object('orderId',oid));raise exception 'Unpaid sample completed';exception when sqlstate 'PT409' then null;end;
 insert into pg_temp.th_sample_results values('Authenticated fixed sample cart, canonical order retries and authoritative prices','PASS');
 perform pg_temp.th_sample_claim(other_user);state:=public.th_api('snapshot');perform pg_temp.th_sample_assert(not exists(select 1 from jsonb_array_elements(state->'orders')x(v) where v->>'id'=oid::text),'other buyer cannot see sample order');
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','sample-foreign-payment-01'));raise exception 'Other buyer paid sample';exception when sqlstate 'PT404' then null;end;
 begin perform public.th_api('sample_complete',jsonb_build_object('orderId',oid));raise exception 'Other buyer completed sample';exception when sqlstate 'PT404' then null;end;
 perform pg_temp.th_sample_claim(buyer);
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','card_demo','outcome','declined','requestKey','sample-decline-payment-01','amount',1));perform pg_temp.th_sample_assert(reply#>>'{payment,status}'='unpaid' and (reply#>>'{attempt,amount}')::int=1640,'decline stays unpaid and ignores browser amount');
 perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','card_demo','outcome','declined','requestKey','sample-decline-payment-01'));
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','sample-decline-payment-01'));raise exception 'Sample payment mismatch accepted';exception when sqlstate 'PT409' then null;end;
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','sample-success-payment-01'));receipt:=reply#>>'{payment,reference}';perform pg_temp.th_sample_assert(left(receipt,12)='DEMO-SAMPLE-' and reply#>>'{payment,status}'='paid_demo','explicit sample receipt');
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','sample-success-payment-01'));perform pg_temp.th_sample_assert(reply#>>'{payment,reference}'=receipt and (select count(*)=2 from public.th_sample_payments where order_id=oid),'payment retries deduplicate');
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','sample-second-payment-01'));raise exception 'Double sample charge accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.th_api('cancel',jsonb_build_object('orderId',oid));raise exception 'Paid sample cancelled';exception when sqlstate 'PT409' then null;end;
 update public.th_sample_orders set expires_at=public.th_now()-1 where id=oid;reply:=public.th_api('snapshot');perform pg_temp.th_sample_assert((select status='reserved' from public.th_sample_orders where id=oid),'paid sample never expires');
 reply:=public.th_api('sample_complete',jsonb_build_object('orderId',oid));perform public.th_api('sample_complete',jsonb_build_object('orderId',oid));
 perform pg_temp.th_sample_assert((select status='completed' and completed_at is not null from public.th_sample_orders where id=oid),'buyer completes sample idempotently');
 perform pg_temp.th_sample_assert(not exists(select 1 from public.th_orders where id=oid) and not exists(select 1 from public.th_order_payments where order_id=oid),'fictional sale never creates actual seller order');
 perform pg_temp.th_sample_claim(other_user);state:=public.th_api('snapshot');perform pg_temp.th_sample_assert(position(receipt in state::text)=0,'sample receipt private to buyer');
 insert into pg_temp.th_sample_results values('Private decline/success receipts, paid protection and completed sample sale','PASS');
 perform pg_temp.th_sample_claim(buyer);reply:=public.th_api('reserve','{"productIds":["p15"],"delivery":"pickup","requestKey":"sample-cancel-order-01"}');cancel_oid:=(reply->>'orderId')::uuid;perform public.th_api('cancel',jsonb_build_object('orderId',cancel_oid));perform pg_temp.th_sample_assert((select status='cancelled' from public.th_sample_orders where id=cancel_oid),'unpaid sample cancellation');
 reply:=public.th_api('reserve','{"productIds":["p15"],"delivery":"pickup","requestKey":"sample-expire-order-01"}');expired_oid:=(reply->>'orderId')::uuid;update public.th_sample_orders set expires_at=public.th_now()-1 where id=expired_oid;perform public.th_api('snapshot');perform pg_temp.th_sample_assert((select status='expired' from public.th_sample_orders where id=expired_oid),'unpaid sample expiry');
 begin perform public.th_api('pay',jsonb_build_object('orderId',expired_oid,'method','qr_demo','outcome','success','requestKey','sample-expired-payment-01'));raise exception 'Expired sample paid';exception when sqlstate 'PT409' then null;end;
 perform public.th_api('cart_add','{"productId":"p15"}');reply:=public.th_api('cart_remove','{"productId":"p15"}');perform pg_temp.th_sample_assert(not(reply->'cart' @> '["p15"]'::jsonb),'sample cart removal');
 perform pg_temp.th_sample_assert((select count(*)=0 from public.th_shops where user_id in(buyer,other_user) and status='verified'),'sample purchases never fake shop verification');
 insert into pg_temp.th_sample_results values('Unpaid cancel/expiry and no counterfeit seller identity','PASS');
end$$;
set local role authenticated;
do $$begin
 begin perform 1 from public.th_sample_orders;raise exception 'Direct sample orders readable';exception when insufficient_privilege then null;end;
 begin perform 1 from public.th_sample_cart;raise exception 'Direct sample cart readable';exception when insufficient_privilege then null;end;
 begin perform 1 from public.th_sample_payments;raise exception 'Direct sample payments readable';exception when insufficient_privilege then null;end;
 begin perform public.th_api_v4_base('snapshot');raise exception 'Previous dispatcher bypass exposed';exception when insufficient_privilege then null;end;
 begin perform public.th_sample_payment('96000000-7a21-4000-8000-000000000001');raise exception 'Private sample payment helper exposed';exception when insufficient_privilege then null;end;
end$$;
reset role;
select stage,result from pg_temp.th_sample_results;
rollback;
